cmd_summary() {
 if [ "$(is_dart_repo)" != "1" ]; then
   echo "toolchain: dart none (CI: none, match: n/a) — not a Dart repo (no pubspec.yaml); SDK install skipped"
   return 0
 fi

 # Resolve the leg's target exactly like the install path does (same
 # precedence), so the summary describes the toolchain the session runs.
 resolve_target ""

 local pin_kind="version" running effective match
 # The CI slot reports the repo's pin — the SAME value the install path
 # consumed, taken from resolve_target's result so summary and install can
 # never drift (gh-1137 review: a raw re-read reported a v-prefixed token
 # the install path had already stripped → false match: no).
 case "${SOURCE}" in
   "version file"|"quality workflow")
     # resolve_target consumed the repo pin: VERSION (already v-stripped)
     # in version mode, the resolved channel in channel mode.
     if [ "${MODE}" = "version" ]; then
       pin="${VERSION}"
     else
       pin="${CHANNEL}"; pin_kind="channel"
     fi
     ;;
   *)
     # Operator override (argument/environment) or no pin: the CI slot
     # still reports what the repo itself pins, v-prefix stripped like
     # resolve_target does.
     pin="$(repo_version_pin)"
     pin="${pin#v}"
     case "${pin}" in stable|beta|dev) pin_kind="channel" ;; esac
     if [ -z "${pin}" ]; then
       local det_sdk det_channel
       det="$(quality_detection)"
       det="${det#*|}"
       det_sdk="${det%%|*}"; det_channel="${det#*|}"
       if [ -n "${det_sdk}" ]; then
         pin="${det_sdk#v}"; pin_kind="version"
       elif [ -n "${det_channel}" ]; then
         pin="${det_channel}"; pin_kind="channel"
       fi
     fi
     ;;
 esac

 running="$(installed_version)"
