            var cfg = JSON.parse(raw);
            var cmds = (((cfg.params || {}).customParams) || {}).setupCommands || [];
            cmds.forEach(function (cmd) {
                if (/dart\.sh/.test(String(cmd))) {
                    assert.ok(/^bash (agents\/)?setup\/dart\.sh$/.test(String(cmd).trim()),
