       'bash "$r/setup/dart.sh" ' + subcommand);
   lines.push('rc=$?');
   if (opts.trailTarget !== undefined) { ... postamble }
   lines.push('cd /; rm -rf "$d"');
   lines.push('exit $rc');
   return dsParseKv(cli_execute_command({ command: 'bash -c ' + dsShq(lines.join('\n')) }));
}
``

