75:/**
76: * Run `setup/dart.sh <subcommand>` inside a fresh mktemp sandbox.
77: * opts: qualityYml — contents written to <sandbox>/.github/workflows/quality.yml
78: *       env        — extra `KEY=value` strings prefixed to the invocation
79: *       stubDart   — version banner a fake `dart` on PATH prints (status tests)
80: */
81:function dsRun(subcommand, opts) {
82:    opts = opts || {};
83:    var lines = ['r="$(pwd)"', 'd="$(mktemp -d)"'];
84:    if (opts.qualityYml !== undefined) {
85:        lines.push('mkdir -p "$d/.github/workflows"');
86:        lines.push('printf %s ' + dsShq(opts.qualityYml) + ' > "$d/.github/workflows/quality.yml"');
87:    }
88:    if (opts.stubDart !== undefined) {
89:        lines.push('mkdir -p "$d/bin"');
90:        // The banner is quoted INSIDE the stub script (dsShq(opts.stubDart) rides
91:        // inside the script text, not as a shell argument) — an unquoted echo
92:        // would die on the banner's parentheses and print no version at all.
93:        lines.push('printf %s ' + dsShq('#!/bin/sh\necho ' + dsShq(opts.stubDart)) + ' > "$d/bin/dart"');
94:        lines.push('chmod +x "$d/bin/dart"');
95:    }
96:    if (opts.managedBanner !== undefined) {
97:        // A fake SDK installed at <DART_INSTALL_DIR>/dart-sdk/bin/dart — what
98:        // dart.sh itself (or a CI cache restore) would have put there.
99:        lines.push('mkdir -p "$d/nodart/dart-sdk/bin"');
100:        lines.push('printf %s ' + dsShq('#!/bin/sh\necho ' + dsShq(opts.managedBanner)) +
101:            ' > "$d/nodart/dart-sdk/bin/dart"');
102:        lines.push('chmod +x "$d/nodart/dart-sdk/bin/dart"');
103:    }
104:    if (opts.stubCurlFails) {
105:        // A curl that always fails — simulates the network-hiccup degraded
106:        // path (channel_latest cannot resolve) without any real network.
107:        lines.push('mkdir -p "$d/bin"');
108:        lines.push('printf %s ' + dsShq('#!/bin/sh\nexit 1') + ' > "$d/bin/curl"');
109:        lines.push('chmod +x "$d/bin/curl"');
110:    }
111:    if (opts.versionFile !== undefined) {
112:        // The repo's version-file pin convention (gh-1137): a one-token
113:        // .dart-version at the repo root — the first pin source checked.
114:        lines.push('printf %s ' + dsShq(opts.versionFile) + ' > "$d/.dart-version"');
115:    }
116:    if (opts.pubspec) {
117:        // Marks the sandbox checkout as a Dart repo (gh-1137: the stable
118:        // fallback and its loud warning apply to Dart repos; a non-Dart
119:        // repo skips the SDK install entirely).
120:        lines.push('printf %s ' + dsShq('name: sandbox\nenvironment:\n  sdk: ^3.0.0\n') + ' > "$d/pubspec.yaml"');
121:    }
122:    var env = (opts.env || []).slice();
123:    // Hermetic against the HOST: the script's installed-version probe falls
124:    // back to <DART_INSTALL_DIR>/dart-sdk/bin/dart, so a real SDK cached on
125:    // the runner (or left by a manual install — live: the verification step
126:    // of this very ticket) would leak into `status`/`plan`. Point the
127:    // install dir INSIDE the sandbox for every invocation.
128:    env.push('DART_INSTALL_DIR="$d/nodart"');
129:    if (opts.noHostDart) {
130:        // Hermetic against a dart already on the host PATH: only the sandbox bin + system dirs.
131:        lines.push('mkdir -p "$d/bin"');
132:        env.push('PATH="$d/bin:/usr/bin:/bin"');
133:    } else if (opts.stubDart !== undefined || opts.stubCurlFails) {
134:        env.push('PATH="$d/bin:$PATH"');
135:    }
136:    if (opts.trailTarget !== undefined) {
137:        // register_path's parent-visible trail (/tmp/_registered_paths) is
138:        // how the sandbox can observe WHICH dirs the script put on PATH for
139:        // the leg session — the only observable for the degraded-branch lie.
140:        // trailTarget may reference the sandbox dir as $d — expanded by the
141:        // wrapper shell (double-quoted), NOT by dsShq.
142:        lines.push('touch /tmp/_registered_paths');
143:        lines.push('before=$(wc -l < /tmp/_registered_paths)');
144:        lines.push('dpath="' + opts.trailTarget + '"');
145:    }
146:    lines.push('cd "$d"');
147:    lines.push((env.length ? env.join(' ') + ' ' : '') +
148:        'bash "$r/setup/dart.sh" ' + subcommand);
149:    lines.push('rc=$?');
150:    if (opts.trailTarget !== undefined) {
151:        lines.push('after=$(wc -l < /tmp/_registered_paths 2>/dev/null || echo 0)');
152:        lines.push('trail_hit=0');
153:        lines.push('if [ "$after" -gt "$before" ] && tail -n "+$((before + 1))" /tmp/_registered_paths 2>/dev/null | grep -qF -- "$dpath"; then trail_hit=1; fi');
154:        lines.push('echo "trail_hit=$trail_hit"');
155:    }
156:    lines.push('cd /; rm -rf "$d"');
157:    lines.push('exit $rc');
158:    return dsParseKv(cli_execute_command({ command: 'bash -c ' + dsShq(lines.join('\n')) }));
159:}
