76: * Run `setup/dart.sh <subcommand>` inside a fresh mktemp sandbox.
77: * opts: qualityYml — contents written to <sandbox>/.github/workflows/quality.yml
78: *       env        — extra `KEY=value` strings prefixed to the invocation
79: *       stubDart   — version banner a fake `dart` on PATH prints (status tests)
80: */
81:function dsRun(subcommand, opts) {
82:    opts = opts || {};
83:    var lines = ['r="$(pwd)"', 'd="$(mktemp -d)"'];
84:    if (opts.qualityYml !== undefined) {
85:        lines.push('mkdir -p "$d/.github/workflows"');
86:        lines.push('printf %s ' + dsShq(opts.qualityYml) + ' > "$d/.github/workflows/quality.yml"');
87:    }
88:    if (opts.stubDart !== undefined) {
89:        lines.push('mkdir -p "$d/bin"');
90:        // The banner is quoted INSIDE the stub script (dsShq(opts.stubDart) rides
