   opts = opts || {};
   var sandbox = dsSandbox(opts);
   var lines = sandbox.lines;
   var env = dsSandboxEnv(sandbox, opts);
   lines.push('cd "$d"');
   lines.push('out="$( (' + (env.length ? env.join(' ') + ' : '') +
       'bash "$r/setup/dart.sh" ' + subcommand + ') 2>&1 )"; rc=$?');
